import { db } from "@/db";
import { bets, players } from "@/db/schema";
import { and, desc, eq, lt } from "drizzle-orm";
import { randomUUID } from "crypto";

export const dynamic = "force-dynamic";

const START_BALANCE = 100000; // R$ 1.000,00
const STALE_MINUTES = 6;

async function snapshot(playerId: string) {
  const [player] = await db.select().from(players).where(eq(players.id, playerId));
  const history = await db
    .select()
    .from(bets)
    .where(eq(bets.playerId, playerId))
    .orderBy(desc(bets.id))
    .limit(12);
  return { playerId, balance: player.balance, history };
}

export async function POST(req: Request) {
  const body = (await req.json().catch(() => ({}))) as {
    playerId?: string;
    action?: string;
  };

  let playerId = body.playerId;
  if (playerId) {
    const [exists] = await db.select().from(players).where(eq(players.id, playerId));
    if (!exists) playerId = undefined;
  }
  if (!playerId) {
    playerId = randomUUID();
    await db.insert(players).values({ id: playerId, balance: START_BALANCE });
  }

  // Apostas abandonadas (partida nunca finalizada) contam como perdidas.
  const cutoff = new Date(Date.now() - STALE_MINUTES * 60 * 1000);
  await db
    .update(bets)
    .set({ status: "lost", settledAt: new Date() })
    .where(and(eq(bets.playerId, playerId), eq(bets.status, "open"), lt(bets.createdAt, cutoff)));

  if (body.action === "refill") {
    const [p] = await db.select().from(players).where(eq(players.id, playerId));
    if (p && p.balance < 1000) {
      await db.update(players).set({ balance: START_BALANCE }).where(eq(players.id, playerId));
    }
  }

  return Response.json(await snapshot(playerId));
}
