import {
  doublePrecision,
  integer,
  pgTable,
  serial,
  text,
  timestamp,
} from "drizzle-orm/pg-core";

// Valores em centavos (inteiros) para evitar erro de ponto flutuante.
export const players = pgTable("players", {
  id: text("id").primaryKey(),
  balance: integer("balance").notNull().default(100000),
  createdAt: timestamp("created_at").notNull().defaultNow(),
});

export const bets = pgTable("bets", {
  id: serial("id").primaryKey(),
  playerId: text("player_id")
    .notNull()
    .references(() => players.id),
  homeId: text("home_id").notNull(),
  awayId: text("away_id").notNull(),
  pick: text("pick").notNull(), // home | draw | away
  stake: integer("stake").notNull(),
  odds: doublePrecision("odds").notNull(),
  status: text("status").notNull().default("open"), // open | won | lost
  homeGoals: integer("home_goals"),
  awayGoals: integer("away_goals"),
  payout: integer("payout").notNull().default(0),
  createdAt: timestamp("created_at").notNull().defaultNow(),
  settledAt: timestamp("settled_at"),
});
